/bin/bash -lc "cd [workspace path] && python3 << 'EOF'
import numpy as np
p = np.load('source_pixels.npz')['rgb']
f0 = p[0].astype(int)
r,g,b = f0[...,0],f0[...,1],f0[...,2]
green = (g > r) & (g > b)
nong = ~green
# connected components on non-green via simple flood fill (small image)
from collections import deque
H,W = nong.shape
seen = np.zeros_like(nong, bool)
comps=[]
for y in range(H):
    for x in range(W):
        if nong[y,x] and not seen[y,x]:
            q=deque([(y,x)]); seen[y,x]=True; pts=[]
            while q:
                cy,cx=q.popleft(); pts.append((cy,cx))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and nong[ny,nx] and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx))
            if len(pts)>30:
                ys=[a for a,_ in pts]; xs=[b_ for _,b_ in pts]
                comps.append((len(pts), min(xs),max(xs),min(ys),max(ys)))
comps.sort(reverse=True)
for c in comps[:25]: print(c)
EOF"
